Certainly! Here's a simple C++ function that calculates the integral of a given function using the trapezoidal rule:

```cpp
#include <iostream>
#include <functional>

double trapezoidalRule(std::function<double(double)> func, double a, double b, int n) {
    double h = (b - a) / n;
    double integral = 0.5 * (func(a) + func(b));

    for (int i = 1; i < n; ++i) {
        double x = a + i * h;
        integral += func(x);
    }

    integral *= h;
    return integral;
}

int main() {
    auto myFunction = [](double x) { return x * x; }; // Example: f(x) = x^2
    double a = 0.0;
    double b = 1.0;
    int n = 100; // Number of intervals

    double result = trapezoidalRule(myFunction, a, b, n);
    std::cout << "Integral: " << result << std::endl;

    return 0;
}
```

This function, `trapezoidalRule`, takes a function `func`, the lower limit `a`, the upper limit `b`, and the number of intervals `n`. It calculates the integral using the trapezoidal rule by dividing the interval into `n` subintervals and summing the areas of the trapezoids formed. You can replace `myFunction` with any function you want to integrate.

